Chủ yếu cung cấp VPP doanh nghiệp, chưa xác minh có quầy bán lẻ."},{"district":"Huyện Cần Đước","name":"Nhà sách Lê Hoàng","address_line":"Ấp 5, xã Long Hòa cũ (khu Rạch Kiến), huyện Cần Đước","category":"nha_sach","phone":"02723880145","tax_code":null,"source_key":"gmap:ChIJxzQJAPk0dTER_S1DoGK6_7A","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20L%C3%AA%20Ho%C3%A0ng%20R%E1%BA%A1ch%20Ki%E1%BA%BFn%20Long%20An&query_place_id=ChIJxzQJAPk0dTER_S1DoGK6_7A","verification_note":"Chưa có số nhà, điểm cửa hàng ở khu chợ Rạch Kiến cũ."},{"district":"Huyện Cần Đước","name":"Nhà sách Cần Đước","address_line":"Quốc lộ 50, thị trấn Cần Đước cũ (Plus Code GJ33+VJX)","category":"nha_sach","phone":"02723881293","tax_code":null,"source_key":"gmap:ChIJbxkXQEdKdTERBcbznuKDN0s","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20C%E1%BA%A7n%20%C4%90%C6%B0%E1%BB%9Bc%20Long%20An&query_place_id=ChIJbxkXQEdKdTERBcbznuKDN0s","verification_note":"Tên chung, có 2 hồ sơ chi nhánh LABOCO cùng địa bàn; cần xác minh không trùng địa chỉ 90A QL50/224 khu 1A."},{"district":"Huyện Cần Đước","name":"Nhà sách Cần Đước 2 - LABOCO","address_line":"90A Quốc lộ 50, thị trấn Cần Đước cũ","category":"nha_sach","phone":null,"tax_code":"1100112728022","source_key":"tax:1100112728022","source_url":"https://masothue.com/1100112728-cong-ty-co-pha-n-sach-dich-vu-van-hoa-long-an","verification_note":"Khác tên đăng ký với Nhà sách Cần Đước QL50; cần xác minh số nhà trước khi coi là 2 cửa hàng."},{"district":"Huyện Cần Đước","name":"Nhà sách Cần Đước - CN Sách & Dịch vụ Văn hóa","address_line":"224 khu 1A, thị trấn Cần Đước cũ","category":"nha_sach","phone":null,"tax_code":"1100112728005","source_key":"tax:1100112728005","source_url":"https://infodoanhnghiep.com/thong-tin/CN-Cong-ty-CP-Sach-Dich-vu-Van-hoa-Nha-sach-Can-Duoc-12728-005.html","verification_note":"Hồ sơ chi nhánh cũ, xác minh quầy bán có còn ở địa chỉ 224 khu 1A."},{"district":"Huyện Cần Đước","name":"Cửa hàng Sách - Thiết bị giáo dục Rạch Kiến","address_line":"97 ấp 5, xã Long Hòa cũ, huyện Cần Đước","category":"nha_sach","phone":null,"tax_code":"1100105921010","source_key":"tax:1100105921010","source_url":"https://infodoanhnghiep.com/thong-tin/CN-Cty-Co-phan-Cua-hang-Sach-Thiet-bi-giao-duc-Rach-Kien-05921-010.html","verification_note":"Cơ sở chi nhánh có hồ sơ đăng ký tại Rạch Kiến; không mặc định trùng Nhà sách Lê Hoàng."},{"district":"Huyện Cần Đước","name":"Nhà sách Rạch Kiến","address_line":"360 tỉnh lộ 826, ấp 3, xã Long Hòa cũ, huyện Cần Đước","category":"nha_sach","phone":null,"tax_code":null,"source_key":"web:nha-sach-rach-kien-360-tl826","source_url":"https://www.youtube.com/watch?v=6Jd21rnr4pw","verification_note":"Nguồn video/đại lý phân phối sách cũ, chưa có bằng chứng đang hoạt động; cần gọi/xác minh."},{"district":"Huyện Cần Đước","name":"Chi nhánh Cửa hàng Sách - Thiết bị giáo dục Thị trấn Cần Đước","address_line":"86 khóm 5, thị trấn Cần Đước cũ","category":"nha_sach","phone":null,"tax_code":"1100105921014","source_key":"tax:1100105921014","source_url":"https://thongtindoanhnghiep.co/1100105921-cong-ty-co-phan-sach-va-thiet-bi-truong-hoc-long-an","verification_note":"Hồ sơ cũ thuộc LABECO, chưa xác minh hiện trạng quầy."}]'::jsonb) AS x(
  district text,name text,address_line text,category text,phone text,tax_code text,
  source_key text,source_url text,verification_note text)
), ins AS (
 INSERT INTO public.field_prospects(
  id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,
  note,status,source_kind,research_source_key,research_source_url,research_batch
 )
 SELECT
  (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)
   ||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
  NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_line,
  'Long An',s.district,s.category,s.phone,s.tax_code,
  'Nguồn nghiên cứu công khai 21/11/2026. Chưa ghé, GPS chưa xác minh, hoạt động bán lẻ cần Sales xác nhận. '||
  s.verification_note||' Nguồn: '||s.source_url,
  'new','manual',s.source_key,s.source_url,'2026-11-21-long-an-old-wave-01-five-districts'
 FROM src s
 WHERE s.district IN ('Thành phố Tân An','Huyện Bến Lức','Huyện Đức Hòa','Huyện Cần Giuộc','Huyện Cần Đước')
  AND s.source_url LIKE 'https://%'
  AND NOT EXISTS (
    SELECT 1 FROM public.customers c
    WHERE c.province='Long An' AND c.district=s.district
    AND lower(btrim(c.name))=lower(btrim(s.name)))
  AND NOT EXISTS (
    SELECT 1 FROM public.field_prospects p
    WHERE p.province='Long An' AND p.district=s.district
    AND (p.research_source_key=s.source_key OR
      (lower(btrim(p.name))=lower(btrim(s.name)) AND lower(btrim(p.address_line))=lower(btrim(s.address_line)))))
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING district,name,phone,tax_code
)
SELECT district,count(*)::int inserted,
 count(*) FILTER(WHERE phone IS NOT NULL)::int phones,
 count(*) FILTER(WHERE tax_code IS NOT NULL)::int taxes
FROM ins GROUP BY district ORDER BY district;